const id=()=>Date.now()+Math.floor(Math.random()*999);
function statusMulta(v){
  v=String(v||'').toLowerCase().trim();
  if(['pago','pagas'].includes(v)) return 'pago';
  if(['aceito','aceita','aceito_cdt','aceita_cdt','aceito_snt','aceita_snt'].includes(v)) return 'aceito';
  if(['aguardando_assinatura','aguardando assinatura','assinatura','aguardando_assinar'].includes(v)) return 'aguardando_assinatura';
  if(['aguardando_aceite','aguardando_motorista','pendente','vencido'].includes(v)) return 'aguardando_aceite';
  if(['recorrida','em_analise','em análise','analise'].includes(v)) return 'recorrida';
  if(['sem_necessidade','sem necessidade','s/ necessidade','s/ nessecidade'].includes(v)) return 'sem_necessidade';
  if(['demitido','motorista_demitido'].includes(v)) return 'demitido';
  return v || 'aguardando_aceite';
}
function inferStatusMulta(r){
  const ass=String(r.assinado||'').toUpperCase().trim();
  const pg=String(r.pago||'').toUpperCase().trim();
  const obs=String(r.obs||'').toUpperCase();
  const t=[r.assinado,r.obs,r.pago,r.envioRCA,r.envio_rca,r.dp].join(' ').toUpperCase();
  if(t.includes('RECORR')) return 'recorrida';
  if(t.includes('AGUARDANDO ASSINATURA') || t.includes('ASSINATURA PENDENTE')) return 'aguardando_assinatura';
  if(t.includes('DEMIT')) return 'demitido';
  if(pg==='OK') return 'pago';
  if(obs.includes('AGUARD') && obs.includes('ACEITE')) return 'aguardando_aceite';
  if(ass==='OK') return 'aceito';
  if(t.includes('S/') || t.includes('SEM COBRAN') || t.includes('S/N')) return 'sem_necessidade';
  return 'aguardando_aceite';
}
function multaFromDb(row){
  return {
    id:Number(row.id),
    linha:row.linha||'',
    placa:row.carro||row.placa||'',
    data:row.data||row.vencimento||'',
    hora:row.hora||'',
    motorista:row.motorista||'S/N',
    municipio:row.municipio||'',
    local:row.local||'',
    infracao:row.infracao||'',
    auto:row.auto||'',
    valor:Number(row.valor||0),
    status:statusMulta(row.status)||inferStatusMulta(row),
    pago:row.pago||'',
    assinado:row.assinado||'',
    envioRCA:row.envio_rca||row.envioRCA||'',
    prazo:row.prazo_aceite||row.prazoAceite||row.prazo||'',
    obs:row.obs||'',
    dp:row.dp||'',
    dataSuspeita:!!(row.data_suspeita||row.dataSuspeita)
  };
}
function multaToDb(r){
  const status=statusMulta(r.status)||inferStatusMulta(r);
  return {
    id:Number(r.id),
    linha:String(r.linha??'manual'),
    carro:r.placa||'',
    placa:r.placa||'',
    data:r.data||'',
    hora:r.hora||'',
    local:r.local||'',
    municipio:r.municipio||'',
    infracao:r.infracao||'',
    auto:r.auto||'',
    motorista:r.motorista||'S/N',
    valor:Number(r.valor||0),
    assinado:r.assinado||'',
    pago:r.pago||'',
    envio_rca:r.envioRCA||'',
    prazo_aceite:r.prazo||'',
    dp:r.dp||'',
    status,
    obs:r.obs||'',
    data_suspeita:!!r.dataSuspeita
  };
}
function connectSupabase(){
  try{
    if(!window.supabase) return null;
    if(!supabaseClient) supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_ANON_KEY);
    return supabaseClient;
  }catch(e){console.warn('Supabase indisponível:',e);return null;}
}
async function carregarMultasSupabase(){
  const db=connectSupabase();
  if(!db) return;
  try{
    const {data:rows,error}=await db.from('multas').select('*').order('id',{ascending:false});
    if(error) throw error;
    data.multas=(rows||[]).map(multaFromDb);
    renderNav();
    if(currentPage==='multas'||currentPage==='dashboard') showPage(currentPage);
    /* aviso automático removido: multas carregadas do Supabase */
  }catch(e){
    console.error(e);
    toast('Não foi possível carregar multas do Supabase.');
  }
}
async function salvarMultaSupabase(obj){
  const db=connectSupabase();
  if(!db) return false;
  const payload=multaToDb(obj);
  delete payload.descricao;
  delete payload.descricao_multa;
  delete payload.obs_descricao;
  const {data:row,error}=await db.from('multas').upsert(payload,{onConflict:'id'}).select().single();
  if(error) throw error;
  Object.assign(obj,multaFromDb(row));
  return true;
}
async function removerMultaSupabase(itemId){
  const db=connectSupabase();
  if(!db) return false;
  const {error}=await db.from('multas').delete().eq('id',itemId);
  if(error) throw error;
  return true;
}

