function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
function init(){renderNav();showPage('dashboard');carregarMultasSupabase()}

function addedKeyMulta(r){
  const n=Number(r?.id);
  if(Number.isFinite(n)) return n;
  const raw=String(r?.created_at||r?.createdAt||r?.inserted_at||r?.updated_at||'');
  const t=Date.parse(raw);
  return Number.isFinite(t)?t:0;
}
function priorityClassMulta(r){
  const d=daysUntil(r?.prazo);
  if(typeof d==='number' && d<=7) return 'priority-urgent';
  if(typeof d==='number' && d<=30) return 'priority-warn';
  return 'priority-ok';
}
function priorityStatusLabel(r){
  const st=statusMulta(r?.status);
  if(st==='aguardando_assinatura') return 'Assinatura';
  if(st==='aguardando_aceite') return 'Aceite';
  return statusNice(st);
}
function priorityPrazoLabel(r){
  const d=daysUntil(r?.prazo);
  if(typeof d==='number') return d<0 ? `Vencido ${Math.abs(d)}d` : `${d}d`;
  return 'Sem prazo';
}
function renderNav(){
  const nav=document.getElementById('nav');
  if(currentPage==='multas' && multasSidebarCollapsed){
    const shortcuts=[
      ['', 'Todos'],['aguardando_aceite','Aguardando aceite'],['aguardando_assinatura','Aguardando assinatura'],['pago','Pagas'],['aceito','Aceitas CDT/SNT'],['recorrida','Recorridas'],['sem_necessidade','Sem necessidade'],['demitido','Demitido']
    ];
    const countStatus=st=>st?data.multas.filter(r=>statusMulta(r.status)===st).length:data.multas.length;
    const priority=data.multas.filter(r=>['aguardando_aceite','aguardando_assinatura'].includes(statusMulta(r.status))).sort((a,b)=>{
      const da=daysUntil(a.prazo), db=daysUntil(b.prazo);
      const va=typeof da==='number'?da:999999, vb=typeof db==='number'?db:999999;
      return va-vb || addedKeyMulta(b)-addedKeyMulta(a);
    }).slice(0,5);
    nav.innerHTML=`<button class="sidebar-back" onclick="toggleMultasSidebar(false)"><span>← Outros módulos</span></button><div class="shortcut-title">Atalhos</div>`+
      shortcuts.map(([st,label])=>`<button class="shortcut-btn ${selectedMultaStatus===st?'shortcut-active':''}" onclick="selectMultaStatus('${st}')"><span class="nav-label">${label}</span><span class="pill shortcut-pill">${countStatus(st)}</span></button>`).join('')+
      `<div class="shortcut-title">Prioridade</div>`+
      (priority.length?priority.map(r=>`<button class="priority-card ${priorityClassMulta(r)}" onclick="openForm('multas',${r.id})"><span class="priority-plate">${esc(r.placa||'-')}</span><span class="priority-status tag amber">${esc(priorityStatusLabel(r))}</span><span class="priority-name">${esc(r.motorista||'Sem motorista')}</span><span class="priority-meta"><span>${fmtDate(r.data)} • Auto ${esc(r.auto||'-')}</span><span class="priority-prazo">${priorityPrazoLabel(r)}</span></span></button>`).join(''):'<div class="collapse-hint">Nenhuma multa pendente em prioridade.</div>')+
      `<div class="collapse-hint">Clique em “Outros módulos” para abrir as demais abas. Ao clicar em Multas novamente, os atalhos voltam.</div>`;
    return;
  }
  nav.innerHTML=pages.map(([key,title])=>`<button data-page="${key}" class="${key===currentPage?'active':''}">${title}<span class="pill">${countFor(key)}</span></button>`).join('');
  document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
}
function toggleMultasSidebar(collapsed){multasSidebarCollapsed=collapsed;renderNav()}
function selectMultaStatus(st){selectedMultaStatus=st;render_multas();renderNav()}
function daysUntil(d){if(!/^\d{4}-\d{2}-\d{2}$/.test(d||''))return 'sem prazo';const today=new Date();today.setHours(0,0,0,0);return Math.ceil((new Date(d+'T00:00:00')-today)/86400000)}
function countFor(k){return k==='dashboard'?'':k==='pontos'?Object.keys(pointSummary()).length:k==='oleo'?data.oleo.length:k==='producao'?data.producaoMeses.length:(data[k]||[]).length}
function setActions(html=''){document.getElementById('pageActions').innerHTML=html}
function showPage(p){currentPage=p;if(p==='multas')multasSidebarCollapsed=true;document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));document.getElementById(p).classList.add('active');const meta=pages.find(x=>x[0]===p);document.getElementById('pageTitle').textContent=meta[1];document.getElementById('pageSub').textContent=meta[2];renderNav();window['render_'+p]?.()}
function stats(items){return `<div class="stats">${items.map(x=>`<div class="stat"><span>${x[0]}</span><strong>${x[1]}</strong><em>${x[2]||''}</em></div>`).join('')}</div>`}
function statusTag(v){let vv=String(v||'').toLowerCase();let c=vv==='pago'||vv==='ativo'||vv==='concluido'||vv==='ok'||vv==='baixo'?'green':vv==='pendente'||vv==='atenção'||vv==='aguardando_aceite'||vv==='aguardando_assinatura'||vv==='medio'||vv==='médio'?'amber':vv==='vencido'||vv==='inativo'||vv==='alto'?'red':vv==='critico'||vv==='crítico'?'risk-critical':vv==='aceito'?'blue':vv==='recorrida'?'violet':'gray';return `<span class="tag ${c}">${esc(statusNice(v))}</span>`}
function gravidadeTag(v){const c=clean(v);let cls=c.includes('gravissima')?'sev-gravissima':c.includes('grave')?'sev-grave':c.includes('media')?'sev-media':'sev-leve';return `<span class="tag ${cls}">${esc(v||'-')}</span>`}
function riscoPontosTag(p){p=Number(p||0);return p>=20?'<span class="tag risk-critical">crítico</span>':p>=15?'<span class="tag risk-high">alto</span>':p>=8?'<span class="tag risk-mid">atenção</span>':'<span class="tag risk-low">baixo</span>'}
function statusNice(v){const map={aguardando_aceite:'Aguardando aceite',aguardando_assinatura:'Aguardando assinatura',pago:'Paga',aceito:'Aceita no CDT/SNT',recorrida:'Recorrida / em análise',sem_necessidade:'Sem necessidade',demitido:'Motorista demitido',ativo:'Ativo',ferias:'Férias',afastado:'Afastado',inativo:'Inativo',concluido:'Concluído',pendente:'Pendente',manutencao:'Manutenção'};return map[String(v||'').toLowerCase()]||String(v||'-').replaceAll('_',' ')}
function optionLabel(prop,o){if(prop==='status')return statusNice(o);if(prop==='pago'&&o==='OK')return 'Pago';return o||'Pendente'}
function render_dashboard(){setActions('<button class="btn" onclick="exportCSV(\'multas\')">Exportar multas CSV</button>');const totalMan=data.manutencoes.reduce((s,r)=>s+(+r.valor||0),0);document.getElementById('dashboard').innerHTML=stats([['Veículos',data.veiculos.length,'veículos cadastrados'],['Motoristas',data.motoristas.length,'cadastros'],['Multas',data.multas.length,'registros'],['Manutenção',BRL(totalMan),'valor total']])+`<div class="table-card"><div class="table-head"><h3>Visão geral</h3><small>Dados carregados no arquivo</small></div><div class="table-scroll"><table><thead><tr><th>Módulo</th><th>Descrição</th><th>Status</th></tr></thead><tbody>${pages.filter(p=>p[0]!=='dashboard').map(p=>`<tr><td><b>${p[1]}</b></td><td>${p[2]}</td><td>${statusTag('ativo')}</td></tr>`).join('')}</tbody></table></div></div>`}
function render_multas(){setActions('<button class="btn" onclick="exportCSV(\'multas\')">Exportar CSV</button><button class="btn primary" onclick="openForm(\'multas\')">+ Nova multa</button>');let meses=[...new Set(data.multas.map(r=>ym(r.data)))].sort();const statusLabel=selectedMultaStatus?statusNice(selectedMultaStatus):'Todos';document.getElementById('multas').innerHTML=stats([['Total',data.multas.length,'multas'],['Valor',BRL(data.multas.reduce((s,r)=>s+r.valor,0)),'soma'],['Pendentes',data.multas.filter(r=>String(r.status).includes('aguardando')).length,'em aberto'],['Filtro',statusLabel,'atalho selecionado']])+`<div class="multas-toolbar"><button class="btn" onclick="toggleMultasSidebar(true)">← Mostrar atalhos da multa</button><small>Use os atalhos laterais para filtrar por situação e priorizar assinatura/aceite.</small></div>`+filterHtml('multasSearch','Buscar placa, motorista, auto...',`<select id="multasMonth"><option value="">Todos os meses</option>${meses.map(m=>`<option value="${m}">${monthName(m)}</option>`).join('')}</select>`)+`<div class="cards" id="multasList"></div>`;['multasSearch','multasMonth'].forEach(x=>document.getElementById(x).oninput=renderMultasList);renderMultasList()}
function renderMultasList(){let q=clean(document.getElementById('multasSearch')?.value),m=document.getElementById('multasMonth')?.value;let arr=data.multas.filter(r=>(!selectedMultaStatus||statusMulta(r.status)===selectedMultaStatus)&&(!m||ym(r.data)===m)&&(!q||clean(Object.values(r).join(' ')).includes(q)));document.getElementById('multasList').innerHTML=arr.length?arr.map(r=>{const st=statusMulta(r.status);const cardCls=st==='pago'?'multa-ok':st==='aceito'||st==='recorrida'?'multa-info':st==='demitido'?'multa-red':'multa-warn';return `<article class="fine-card ${cardCls}"><div><span class="plate">${esc(r.placa)}</span><div class="fine-meta">${statusTag(r.status)}</div></div><div><b>${esc(r.motorista)}</b><small>${fmtDate(r.data)} • ${esc(r.hora||'-')} • Auto ${esc(r.auto||'-')}</small><small>${esc(r.infracao||'-')}</small></div><div><b>${esc(r.municipio||'-')}</b><small>${esc(r.local||'-')}</small></div><div><b>${BRL(r.valor)}</b><small>Prazo: ${fmtDate(r.prazo)}</small><small>${r.prazo?daysUntil(r.prazo)+' dias para aceite':'Sem prazo'}</small></div><div class="row-actions"><button class="icon-btn" onclick="openForm('multas',${r.id})">✎</button><button class="icon-btn" onclick="removeItem('multas',${r.id})">×</button></div></article>`}).join(''):'<div class="empty">Nenhuma multa encontrada neste atalho.</div>'}
function pointSummary(){const map={};data.pontos.forEach(p=>{const k=p.motorista;if(!map[k])map[k]={motorista:k,pontos:0,qtd:0,ultimas:[]};map[k].pontos+=Number(p.pontos||0);map[k].qtd++;map[k].ultimas.push(p)});return map}
function render_pontos(){setActions('<button class="btn primary" onclick="openForm(\'pontos\')">+ Lançar ponto</button>');const s=Object.values(pointSummary()).sort((a,b)=>b.pontos-a.pontos);document.getElementById('pontos').innerHTML=stats([['Motoristas',s.length,'com pontos'],['Total pontos',s.reduce((a,b)=>a+b.pontos,0),'somados'],['Alto/crítico',s.filter(x=>x.pontos>=15).length,'exige atenção'],['Maior pontuação',s[0]?.pontos||0,'controle']])+table('Resumo por motorista',['Motorista','Pontos somados','Ocorrências','Risco','Ações'],s.map(r=>`<tr><td><b>${esc(r.motorista)}</b></td><td><b>${r.pontos}</b><div class="progress"><div style="width:${Math.min(r.pontos/40*100,100)}%;background:${r.pontos>=20?'#7f1d1d':r.pontos>=15?'var(--red)':r.pontos>=8?'var(--amber)':'var(--green)'}"></div></div></td><td>${r.qtd}</td><td>${riscoPontosTag(r.pontos)}</td><td></td></tr>`).join(''))+table('Histórico de lançamentos',['Data','Motorista','Placa','Auto','Gravidade','Pontos','Aceitou','Ações'],data.pontos.map(r=>`<tr><td>${fmtDate(r.data)}</td><td>${esc(r.motorista)}</td><td><span class="plate">${esc(r.placa)}</span></td><td>${esc(r.auto)}</td><td>${gravidadeTag(r.gravidade)}</td><td><b>${r.pontos}</b></td><td>${esc(r.aceitou)}</td><td class="row-actions"><button class="icon-btn" onclick="openForm('pontos',${r.id})">✎</button><button class="icon-btn" onclick="removeItem('pontos',${r.id})">×</button></td></tr>`).join(''))}
function render_motoristas(){setActions('<button class="btn primary" onclick="openForm(\'motoristas\')">+ Novo motorista</button>');const ps=pointSummary();data.motoristas.forEach(m=>m.pontos=ps[m.nome]?.pontos||0);document.getElementById('motoristas').innerHTML=stats([['Motoristas',data.motoristas.length,'cadastrados'],['Ativos',data.motoristas.filter(x=>x.status==='ativo').length,'em operação'],['Com pontos',data.motoristas.filter(x=>x.pontos>0).length,'pontuação somada'],['CNH informada',data.motoristas.filter(x=>x.cnh).length,'cadastros']])+filterHtml('motSearch','Buscar motorista, CPF, CNH, função ou departamento...')+`<div class="driver-list-toggle"><small class="status-select-note">Visual limpo inspirado no interface_clean, mantendo edição e CNH.</small></div><div class="driver-grid" id="motoristasGrid"></div>`;document.getElementById('motSearch').oninput=renderMotoristasList;renderMotoristasList()}
