function render_veiculos(){setActions('<button class="btn primary" onclick="openForm(\'veiculos\')">+ Novo veículo</button>');document.getElementById('veiculos').innerHTML=stats([['Veículos',data.veiculos.length,'cadastrados'],['Ativos',data.veiculos.filter(x=>x.status==='ativo').length,'operando'],['Manutenção',data.veiculos.filter(x=>x.status==='manutencao').length,'parados'],['Ano médio',Math.round(data.veiculos.reduce((s,x)=>s+x.ano,0)/data.veiculos.length),'controle']])+simpleTable('veiculos',['Placa','Modelo','Linha','Ano','Motorista','Status'])}
function monthFoldersHtml(key,selectedVar,selectFn){
  const arr=data[key]||[];
  const meses=[...new Set(arr.map(r=>ym(r.data)).filter(Boolean))].sort();
  const folders=[{mes:'',label:'Todos os meses'},...meses.map(m=>({mes:m,label:monthName(m)}))];
  const selected=window[selectedVar]||'';
  return `<div class="folders">${folders.map(f=>{let rows=arr.filter(r=>!f.mes||ym(r.data)===f.mes);return `<button class="folder ${selected===f.mes?'active':''}" onclick="${selectFn}('${f.mes}')"><div class="folder-icon">📁</div><strong>${f.label}<span class="folder-count">${rows.length}</span></strong><small>Baseado na data lançada</small></button>`}).join('')}</div>`;
}
