function oilStatus(r){
  if(!/^\d{4}-\d{2}-\d{2}$/.test(r.data||'')) return {diff:null,tag:'gray',text:'Data não informada'};
  const base=new Date(r.data+'T00:00:00'), today=new Date();
  today.setHours(0,0,0,0);
  const expire=new Date(base);
  expire.setMonth(expire.getMonth()+3);
  const diff=Math.ceil((expire-today)/86400000);
  let tag=diff<=30?'red':diff<=60?'amber':'green';
  return {diff,tag,text:diff<0?`Vencido há ${Math.abs(diff)} dias`:diff===0?'Vence hoje':`Faltam ${diff} dias`}
}
function render_oleo(){setActions('<button class="btn primary" onclick="openForm(\'oleo\')">+ Nova troca</button>');const allRows=data.oleo.map(r=>({...r,st:oilStatus(r)}));const rows=allRows.filter(r=>!selectedOleoMonth||ym(r.data)===selectedOleoMonth);document.getElementById('oleo').innerHTML=stats([['Trocas',allRows.length,'cadastradas'],['Verde',allRows.filter(x=>x.st.tag==='green').length,'61 a 90 dias'],['Amarelo',allRows.filter(x=>x.st.tag==='amber').length,'31 a 60 dias'],['Vermelho',allRows.filter(x=>x.st.tag==='red').length,'até 30 dias/vencido']])+monthFoldersHtml('oleo','selectedOleoMonth','selectOleoMonth')+filterHtml('oleoSearch','Buscar placa, KM ou observação...')+`<div id="oleoTable"></div>`;document.getElementById('oleoSearch').oninput=renderOleoList;renderOleoList()}
