function manRowsByMonth(m){return data.manutencoes.filter(r=>!m||ym(r.data)===m)}
function manTotal(rows){return rows.reduce((s,r)=>s+Number(r.valor||0),0)}
function manutencoesFoldersHtml(){
  const meses=[...new Set(data.manutencoes.map(r=>ym(r.data)).filter(Boolean))].sort();
  const folders=['',...meses];
  return `<div class="folders">${folders.map(m=>{
    const rows=manRowsByMonth(m);
    const total=manTotal(rows);
    const unique=new Set(rows.map(r=>r.placa).filter(Boolean)).size;
    return `<button class="folder ${selectedManMonth===m?'active':''}" onclick="selectManMonth('${m}')"><div class="folder-icon">📁</div><strong>${m?monthName(m):'Todos os meses'}</strong><small>${rows.length} registros • ${unique} veículos</small><small class="warn">Total: ${BRL(total)}</small></button>`
  }).join('')}</div>`;
}
function render_manutencoes(){setActions('<button class="btn primary" onclick="openForm(\'manutencoes\')">+ Nova manutenção</button>');const rows=manRowsByMonth(selectedManMonth);const total=manTotal(rows);const ticket=rows.length?total/rows.length:0;document.getElementById('manutencoes').innerHTML=stats([['Registros',rows.length,selectedManMonth?'no mês selecionado':'total de serviços'],['Valor',BRL(total),selectedManMonth?'total do mês':'total geral'],['Ticket médio',BRL(ticket),'valor médio por serviço'],['Selecionado',selectedManMonth?monthName(selectedManMonth):'Todos','pasta atual']])+manutencoesFoldersHtml()+filterHtml('manSearch','Buscar placa, tipo ou origem...')+`<div id="manTable"></div>`;document.getElementById('manSearch').oninput=renderManList;renderManList()}
function renderManList(){let q=clean(document.getElementById('manSearch').value);let arr=data.manutencoes.filter(r=>(!selectedManMonth||ym(r.data)===selectedManMonth)&&(!q||clean(Object.values(r).join(' ')).includes(q)));document.getElementById('manTable').innerHTML=table(selectedManMonth?`Manutenções — ${monthName(selectedManMonth)}`:'Manutenções — Todos os meses',['Data lançada','Placa','Tipo/peça','Origem','Descrição','Valor','Status','Ações'],arr.map(r=>`<tr><td>${fmtDate(r.data)}</td><td><span class="plate">${esc(r.placa)}</span></td><td>${esc(r.tipo)}</td><td>${esc(r.origem)}</td><td>${esc(r.descricao)}</td><td><b>${BRL(r.valor)}</b></td><td>${statusTag(r.status)}</td><td class="row-actions"><button class="icon-btn" onclick="openForm('manutencoes',${r.id})">✎</button><button class="icon-btn" onclick="removeItem('manutencoes',${r.id})">×</button></td></tr>`).join(''))}
function render_producao(){setActions('<button class="btn" onclick="openAddMonth()">+ Pasta/mês</button><button class="btn primary" onclick="openForm(\'producao\')">+ Adicionar dia</button>');const folders=[{mes:'',label:'Todos os meses'},...data.producaoMeses.sort((a,b)=>a.mes.localeCompare(b.mes))];document.getElementById('producao').innerHTML=stats([['Pastas',data.producaoMeses.length,'meses'],['Lançamentos',data.producao.length,'registros'],['Veículos únicos',new Set(data.producao.map(x=>x.placa)).size,'sem duplicar placa'],['Mês atual',selectedProdMonth?monthName(selectedProdMonth):'Todos','selecionado']])+`<div class="folders">${folders.map(f=>{let rows=data.producao.filter(r=>!f.mes||r.mes===f.mes);let unique=new Set(rows.map(r=>r.placa)).size;return `<button class="folder ${selectedProdMonth===f.mes?'active':''}" onclick="selectProdMonth('${f.mes}')"><div class="folder-icon">📁</div><strong>${f.mes?monthName(f.mes):'Todos os meses'}</strong><small>${rows.length} lançamentos • ${unique} veículos únicos</small></button>`}).join('')}</div><div id="prodInfo"></div>`;renderProdInfo(false)}
