function openAddMonth(){const m=prompt('Digite a pasta no formato AAAA-MM:', '2026-06');if(!/^\d{4}-\d{2}$/.test(m||'')){if(m!==null)alert('Use o formato AAAA-MM.');return}if(!data.producaoMeses.some(x=>x.mes===m))data.producaoMeses.push({mes:m});selectedProdMonth=m;toast('Pasta cadastrada criada.');render_producao()}
function filterHtml(input,ph,extra=''){return `<div class="filters"><div class="filter-row ${extra?'':'two'}"><input id="${input}" placeholder="${ph}">${extra||''}</div></div>`}
function table(title,heads,rows){
  if(Array.isArray(rows)) rows=rows.join('');
  rows=rows||'<tr><td colspan="99">Nenhum registro.</td></tr>';
  return `<div class="table-card"><div class="table-head"><h3>${title}</h3><small>Controle</small></div><div class="table-scroll"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div></div>`
}
function simpleTable(key,heads){let rows=data[key].map(r=>`<tr>${heads.slice(0,-1).map(h=>{let prop={'Placa':'placa','Modelo':'modelo','Linha':'linha','Ano':'ano','Motorista':'motorista','Data':'data','Validade':'validade','Status':'status','Obs':'obs'}[h]||h.toLowerCase();let v=r[prop];if(prop==='placa')return `<td><span class="plate">${esc(v)}</span></td>`;if(prop==='data'||prop==='validade')return `<td>${fmtDate(v)}</td>`;if(prop==='status')return `<td>${statusTag(v)}</td>`;return `<td>${esc(v)}</td>`}).join('')}<td class="row-actions"><button class="icon-btn" onclick="openForm('${key}',${r.id})">✎</button><button class="icon-btn" onclick="removeItem('${key}',${r.id})">×</button></td></tr>`).join('');return table(key==='veiculos'?'Veículos':'Tacógrafos',[...heads,'Ações'],rows)}
