function openForm(key,itemId=null){modalCtx={key,itemId};const item=itemId?(data[key].find(x=>x.id===itemId)||{}):{};document.getElementById('modalTitle').textContent=(itemId?'Editar ':'Adicionar ')+labelKey(key);document.getElementById('modalBody').innerHTML=`<div class="form-grid">${schemas[key].map(([prop,label,type])=>field(prop,label,type,item[prop])).join('')}</div>`;document.getElementById('modalBg').classList.add('open')}
function labelKey(k){return ({multas:'multa',pontos:'ponto',motoristas:'motorista',veiculos:'veículo',tacografos:'tacógrafo',oleo:'troca de óleo',manutencoes:'manutenção',producao:'produção'})[k]||k}
function field(prop,label,type,val=''){if(type.startsWith('select:')){let opts=type.split(':')[1].split(',');return `<div class="field"><label>${label}</label><select id="f_${prop}">${opts.map(o=>`<option value="${esc(o)}" ${String(val)===o?'selected':''}>${esc(optionLabel(prop,o))}</option>`).join('')}</select>${prop==='status'?'<div class="status-select-note">Selecione pelo nome amigável; o sistema salva o código correto no banco.</div>':''}</div>`}return `<div class="field"><label>${label}</label><input id="f_${prop}" type="${type}" value="${esc(val)}"></div>`}
async function saveModal(){
  const {key,itemId}=modalCtx;
  const obj=itemId?data[key].find(x=>x.id===itemId):{id:id()};
  schemas[key].forEach(([prop,,type])=>{
    let v=document.getElementById('f_'+prop).value;
    if(type==='number')v=Number(v||0);
    if(prop==='placa')v=v.toUpperCase();
    obj[prop]=v;
  });
  try{
    if(key==='multas') await salvarMultaSupabase(obj);
    if(!itemId)data[key].push(obj);
    if(key==='producao'&&!data.producaoMeses.some(x=>x.mes===obj.mes))data.producaoMeses.push({mes:obj.mes});
    closeModal();
    toast(key==='multas'?'Multa salva no Supabase.':'Alteração salva nesta sessão.');
    showPage(currentPage);
  }catch(e){
    console.error(e);
    alert('Erro ao salvar: '+(e.message||e));
  }
}
function closeModal(){document.getElementById('modalBg').classList.remove('open');modalCtx=null}
async function removeItem(key,itemId){
  if(!confirm('Excluir este registro?'))return;
  try{
    if(key==='multas') await removerMultaSupabase(itemId);
    data[key]=data[key].filter(x=>x.id!==itemId);
    toast(key==='multas'?'Multa excluída do Supabase.':'Registro removido.');
    showPage(currentPage);
  }catch(e){
    console.error(e);
    alert('Erro ao excluir: '+(e.message||e));
  }
}
function exportCSV(key){const rows=data[key]||[];if(!rows.length)return;const cols=Object.keys(rows[0]).filter(c=>c!=='id');const csv=[cols,...rows.map(r=>cols.map(c=>r[c]))].map(row=>row.map(c=>'"'+String(c??'').replace(/"/g,'""')+'"').join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.download=`${key}.csv`;a.click();URL.revokeObjectURL(a.href)}
init();
